        "source_context": {
          "Source A": "Commissioned decades later in 1795, Benjamin West's oil painting depicts Mughal Emperor Shah Alam II at Allahabad in August 1765 handing Robert Clive the Diwani—the legal right to collect land taxes from roughly twenty million people across Bengal, Bihar, and Orissa. **Hinge Question:** Why did East India Company patrons commission a grand ceremonial painting of the 1765 Diwani rather than showing the battlefield violence at Plassey and Buxar that forced the Emperor to sign it?",
          "Source B": "Unveiled in Bolton in September 1862 by public subscription and sculpted by W. Calder Marshall RA, this monument honoured Samuel Crompton (with his ancestral home Hall i' th' Wood carved on the plinth) for inventing the 1779 spinning mule that powered Lancashire's cotton boom. **Hinge Question:** How could the exact same invention be celebrated on a bronze pedestal in Lancashire as heroic progress while being experienced in Dhaka as economic ruin?",
          "Source C": "Passed under fierce lobbying from English woollen and silk weavers, the 1721 Calico Act outlawed wearing or selling printed Indian cotton cloth in Britain, imposing heavy £5 fines on wearers and £20 fines on merchants to shut Indian textiles out of the British market. **Hinge Question:** Why is the 1721 Calico Act crucial evidence against the claim that Lancashire cotton triumphed over Indian textiles purely through fair free-market competition?",
          "Source D": "Giving sworn evidence before a British Parliamentary Select Committee in 1840, colonial administrator Sir Charles Trevelyan documented how high British import tariffs (70–80% on Indian cloth vs 2–3.5% on British factory cotton entering India) emptied historic weaving cities like Dhaka. **Hinge Question:** What does the collapse of Dhaka's population from 150,000 to 30,000 reveal about how colonial trade rules reshaped Indian cities as well as British industrial towns?",
          "Source E": "Attributed to Governor-General Lord William Bentinck's 1834 administrative minute, this famous warning came from the very top of British rule in India—making it especially striking evidence because a colonial governor had no motive to exaggerate British-caused suffering. **Hinge Question:** Why does this bleak verdict carry particular weight coming from Britain's own Governor-General of India rather than from an opponent of British rule?"
        },
