        "hinge_guidance": "Strong answers reject the myth that British steam mills simply won a 'fair free-market race': first, Parliament passed the 1700/1721 Calico Acts (Source C) and 70% import tariffs to lock Indian cloth out of Britain; second, the 1765 Bengal Diwani (Source A) let the Company buy goods using Bengali peasant taxes rather than silver bullion; third, cheap Lancashire factory cloth flooded India virtually tariff-free—devastating Dhaka handloom weavers as admitted by Charles Trevelyan and Governor-General Bentinck (Sources D–E).",
