        "primer": "This enquiry investigates why East India Company rule exploded into massive armed uprising across northern and central India in May 1857. Pupils distinguish long-term structural causes—heavy land taxation, the annexation of Satara, Jhansi, and Awadh under Lord Dalhousie’s Doctrine of Lapse, and fears of Christian missionary interference—from the immediate trigger of greased Pattern 1853 Enfield rifle cartridges, before evaluating why historians debate calling 1857 a 'Sepoy Mutiny' versus a broader 'First War of Independence' and how the 1858 Government of India Act created the direct British Raj.",
