        "source_context": {
          "Source A": "Recorded during the March 1857 unrest at Barrackpore before the May outbreak at Meerut, this testimony shows how the new Pattern 1853 Enfield rifle acted as the final spark atop deeper anger over poor pay, the 1856 General Service Enlistment Act, and the annexation of Awadh. **Hinge Question:** Why do historians view the greased Enfield cartridges as the short-term trigger of 1857 rather than its sole underlying cause?",
          "Source B": "After Maharaja Gangadhar Rao died in 1853, Governor-General Lord Dalhousie used the Doctrine of Lapse to reject Jhansi's adopted heir Damodar Rao and annex the state. In 1857–58, Rani Lakshmibai led Jhansi's defence and died fighting British forces at Gwalior in June 1858. **Hinge Question:** How did Lord Dalhousie's Doctrine of Lapse turn previously allied Indian princely rulers like Rani Lakshmibai into determined military leaders of the 1857 uprising?",
          "Source C": "Issued in August 1857 in the name of Mughal Emperor Bahadur Shah Zafar’s court, the Azamgarh Manifesto deliberately reached beyond army barracks—calling on Hindu and Muslim landowners, merchants, civil servants, and weavers to overthrow East India Company rule together. **Hinge Question:** How does the Azamgarh Proclamation challenge the Victorian British label that 1857 was merely a narrow military 'Sepoy Mutiny'?",
          "Source D": "Published by Cambridge University Press ('Northern India: The Mutiny 1857–9'), this cartographic record highlights both the fierce regional scale of the revolt across Hindustani northern India and the strategic role of telegraph lines, the Grand Trunk Road, and newly opened rail links in British counter-offensives. **Hinge Question:** Why was the geographic concentration of the uprising in northern India—while Bengal ports, Madras, Bombay, and the Punjab did not join—so decisive for Britain's ability to recapture Delhi and Lucknow?",
          "Source E": "Following the Government of India Act (August 1858), which liquidated East India Company rule and transferred sovereignty directly to the British Crown (the British Raj), Queen Victoria's proclamation was read aloud at Allahabad on 1 November 1858 to win back princely loyalty. **Hinge Question:** Did the 1858 creation of the British Raj genuinely empower ordinary Indians, or did it simply replace unstable Company greed with more cautious direct imperial rule?"
        },
