        "primer": "This lesson investigates the colossal imperial expansion between 1884 and 1914 known as the \"Scramble for Africa\". Explores the 1884–85 Berlin Conference where European powers partitioned the African continent without consulting African leaders. Analyzes technological drivers (the Maxim gun, quinine, steam gunboats), economic motives (rubber, gold, diamonds, palm oil), and the conflicting ideological perspectives of Rudyard Kipling (\"The White Man's Burden\") and radical critic E.D. Morel (\"The Black Man's Burden\").",
