          "model_answer": "A primary reason the British Empire remains fiercely debated is the stark contrast between infrastructural modernization and brutal colonial exploitation. Proponents highlight the construction of railways, legal systems, and modern education, arguing it laid the foundations for global commerce.<br><br>Conversely, critics emphasize the devastating economic destruction, racism, and violent repression inflicted on colonized peoples. Policies created man-made famines, such as the 1943 Bengal famine, and displaced indigenous cultures. Therefore, because the Empire brought technological advancement to some while causing immense human suffering and economic drain to millions, its legacy remains deeply contested today.",
