      "extract": "Inside Portsmouth Royal Dockyard in 1805, forty-four steam machines clattered day and night. Engineer Marc Brunel’s block mills carved 130,000 wooden pulley blocks each year for Lord Nelson’s fleet. Factory precision on land now powered mastery across every ocean.\n\nBack in 1776, Scottish thinker Adam Smith had called closed trade rules \"mean and malignant.\" For centuries, Navigation Acts had banned foreign ships from British colonies. Once steam mills made Britain the Workshop of the World, London backed \"Free Trade\" with iron warships instead. HMS Warrior slid down the slipway in 1860 clad in thick wrought-iron plates and rifled guns. Overnight, every wooden sailing warship on earth was left behind.\n\nSteamships soon shrank the globe even more. After the Suez Canal opened across Egypt in 1869, Prime Minister Benjamin Disraeli borrowed four million pounds in 1875 to buy Egypt’s canal shares. That bold purchase gave British warships and cargo steamers the fastest sea shortcut to India.\n\nIn November 1884, European statesmen met in Berlin beneath a fifteen-foot map of Africa. Not one African ruler was invited into the room. Men in dark coats drew straight lines across rivers and kingdoms, turning sea trade into a ruthless race to carve up a continent.",
