      "extract": "On a misty morning in the late 1890s, twenty-four-year-old British shipping clerk Edmund Dene Morel stood on the cobblestones of Antwerp docks. His task for a Liverpool steamship firm looked dull: checking cargo lists for vessels trading with King Leopold II’s Congo Free State.\n\nWeek after week, Morel watched steamers arrive from central Africa crammed with valuable wild rubber and elephant ivory. Then he read the return cargo sheets, and his blood ran cold. No cotton cloth, tools, or coins were sailing back to pay African workers. Instead, ships left Antwerp carrying crates of rifles, ammunition, and iron chains. \"I had stumbled upon a secret society of murderers,\" Morel recalled. Those shipping numbers proved that rubber was being forced from Congolese villagers at gunpoint—sparking Europe’s first mass human-rights campaign.\n\nAcross the North Sea in London, Indian economist Dadabhai Naoroji was reading official British tax books just as closely. Back in 1851, six million visitors to London’s glass Crystal Palace had cheered railways, telegraphs, and steamships as proof that empire helped the world.\n\nElected to Parliament in 1892, Naoroji showed the hidden side of the ledger. Every year, millions of pounds in Indian peasant taxes flowed out to Britain as a silent \"Drain of Wealth,\" leaving families defenceless when terrible famines struck.",
